"""Dependency-free browser surface for the IPM Moment Engine prototype."""

MOMENT_HTML = r'''<!doctype html>
<html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>IPM Moment Engine v0</title>
<style>
:root{color-scheme:dark;--bg:#0c0d0f;--panel:#15171b;--panel2:#1d2025;--line:#32363d;--text:#f2f3f5;--muted:#9ba2ad;--accent:#f2c94c;--live:#75d89a;--danger:#ff7c78}*{box-sizing:border-box}body{margin:0;min-height:100vh;background:var(--bg);color:var(--text);font-family:ui-sans-serif,system-ui,-apple-system,BlinkMacSystemFont,"Segoe UI",sans-serif}button,input,select{font:inherit}button,select,input[type=number],input[type=text]{color:var(--text);background:var(--panel2);border:1px solid var(--line);border-radius:10px}button{cursor:pointer;padding:.72rem .9rem;font-weight:700}button:hover{border-color:#666d78}button.active{border-color:var(--accent);box-shadow:inset 0 0 0 1px var(--accent)}button.recording{border-color:var(--danger);color:var(--danger)}.app{max-width:1120px;margin:0 auto;padding:24px}header{display:flex;justify-content:space-between;gap:20px;align-items:end;margin-bottom:20px}h1{margin:0;font-size:clamp(1.5rem,4vw,2.8rem);letter-spacing:-.04em}.tagline{margin:.45rem 0 0;color:var(--muted);max-width:690px}.badge{color:var(--accent);border:1px solid var(--line);border-radius:999px;padding:.45rem .7rem;white-space:nowrap}.panel{background:var(--panel);border:1px solid var(--line);border-radius:16px;padding:16px;margin-bottom:16px}.transport{display:grid;grid-template-columns:repeat(6,minmax(0,auto));gap:10px;align-items:center}.field{display:grid;gap:5px}.field label,.small{font-size:.78rem;color:var(--muted)}.field input,.field select{min-height:42px;padding:.55rem .7rem;width:100%}.controls{display:grid;grid-template-columns:.8fr 1fr 1fr;gap:18px;align-items:end}.knob{display:grid;grid-template-columns:1fr auto;gap:6px 12px;align-items:center}.knob label{font-weight:800}.knob output{color:var(--accent);font-variant-numeric:tabular-nums}.knob input{grid-column:1/-1;width:100%;accent-color:var(--accent)}.pad-grid{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:12px}.pad{min-height:112px;padding:14px;text-align:left;display:grid;align-content:space-between;border-radius:14px;background:linear-gradient(180deg,#20242a,#17191e);transition:transform 70ms ease,border-color 70ms ease,background 70ms ease}.pad:active,.pad.flash{transform:translateY(2px) scale(.985);background:#292e35}.pad.selected{border-color:var(--accent)}.pad.empty .pad-name{color:#6d747e}.pad-number{font-size:.78rem;color:var(--muted)}.pad-name{font-size:1.05rem;font-weight:800}.pad-meta{font-size:.75rem;color:var(--muted)}.key{float:right;border:1px solid var(--line);border-bottom-width:2px;border-radius:5px;padding:.12rem .32rem;color:var(--muted)}.chain-row{min-height:50px;display:flex;gap:8px;align-items:center;flex-wrap:wrap}.chain-chip{border:1px solid var(--line);background:var(--panel2);border-radius:999px;padding:.35rem .6rem;font-size:.86rem}.two-col{display:grid;grid-template-columns:1.2fr .8fr;gap:16px}.midi-grid{display:grid;grid-template-columns:1fr 1fr auto;gap:10px;align-items:end}.status{min-height:24px;color:var(--muted);font-size:.9rem}.status strong,.rule strong{color:var(--text)}.rule{color:var(--muted);font-size:.88rem;line-height:1.45}footer{color:var(--muted);font-size:.78rem;padding:6px 2px 20px}@media(max-width:800px){.transport,.controls,.two-col,.midi-grid{grid-template-columns:1fr 1fr}header{align-items:start;flex-direction:column}}@media(max-width:560px){.app{padding:14px}.pad-grid{grid-template-columns:repeat(2,minmax(0,1fr))}.transport,.controls,.two-col,.midi-grid{grid-template-columns:1fr}}
</style></head><body><div class="app">
<header><div><h1>Moment Engine <span style="color:var(--accent)">v0</span></h1><p class="tagline">Record a gesture. Store it as one object. Trigger moments the way another instrument triggers notes.</p></div><div class="badge">moment → sentence → composition</div></header>
<section class="panel transport"><button id="recordBtn">● Record selected</button><button id="stopBtn">■ Stop record</button><button id="demoBtn">Load 4 demos</button><button id="chainCaptureBtn">Chain capture</button><button id="playChainBtn">▶ Play chain</button><a href="/api/export" download style="text-decoration:none"><button type="button">Export vocabulary</button></a></section>
<section class="panel controls"><div class="field"><label for="bpm">Tempo</label><input id="bpm" type="number" min="30" max="300" value="120"></div><div class="knob"><label for="repeat">REPEAT</label><output id="repeatOut">1×</output><input id="repeat" type="range" min="1" max="8" value="1"></div><div class="knob"><label for="evolve">EVOLVE</label><output id="evolveOut">0%</output><input id="evolve" type="range" min="0" max="100" value="0"></div><div class="knob" style="grid-column:2/4"><label for="surprise">SURPRISE → RECOVERY</label><output id="surpriseOut">0%</output><input id="surprise" type="range" min="0" max="100" value="0"></div></section>
<section class="panel"><div class="pad-grid" id="pads"></div></section>
<section class="two-col"><div class="panel"><div style="display:flex;justify-content:space-between;gap:12px;align-items:end;margin-bottom:12px"><div><strong>Moment sentence</strong><div class="small">Turn on Chain capture, then play pads. This stores pad order, not steps.</div></div><button id="clearChainBtn">Clear chain</button></div><div class="chain-row" id="chain"></div></div><div class="panel"><strong>Selected moment</strong><div class="field" style="margin-top:10px"><label for="momentName">Name used for next recording</label><input id="momentName" type="text" maxlength="32"></div><button id="clearSlotBtn" style="margin-top:10px">Clear selected slot</button></div></section>
<section class="panel"><div class="midi-grid"><div class="field"><label for="midiIn">MIDI input</label><select id="midiIn"><option>Not connected</option></select></div><div class="field"><label for="midiOut">MIDI output</label><select id="midiOut"><option>Audition synth</option></select></div><button id="midiBtn">Connect MIDI</button></div><p class="rule"><strong>Evaluation rule:</strong> the built-in WebAudio voice is only an audition fallback. For judging whether the idea is musically useful, route MIDI to a real synth. Mutation is deterministic and never invents pitch classes that were not in the recorded moment.</p></section>
<div class="status" id="status">Starting…</div><footer>Keyboard shortcuts trigger moments: 1 2 3 4 / Q W E R / A S D F / Z X C V.</footer></div>
<script>
const padKeys=['1','2','3','4','q','w','e','r','a','s','d','f','z','x','c','v'];let state={slots:[],chain:[]},selectedSlot=1,chainCapture=false,recording=false,recordedEvents=[],activeNotes=new Map(),recordStartMs=null,midiAccess=null,midiInput=null,midiOutput=null,audioContext=null;const $=id=>document.getElementById(id),slotMap=()=>new Map(state.slots.map(i=>[i.slot,i])),msPerBeat=()=>60000/Math.max(30,Math.min(300,Number($('bpm').value)||120));
async function api(path,payload={}){const r=await fetch(path,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(payload)}),d=await r.json().catch(()=>({}));if(!r.ok)throw new Error(d.error||`Request failed: ${r.status}`);return d}function controls(){return{repeats:Number($('repeat').value),evolve:Number($('evolve').value)/100,surprise:Number($('surprise').value)/100}}function esc(t){return String(t).replace(/[&<>'"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[c]))}function status(t,s=''){$('status').innerHTML=s?`<strong>${esc(s)}</strong> ${esc(t)}`:esc(t)}function labels(){$('repeatOut').value=`${$('repeat').value}×`;$('evolveOut').value=`${$('evolve').value}%`;$('surpriseOut').value=`${$('surprise').value}%`}
function renderPads(){const m=slotMap();$('pads').innerHTML='';for(let slot=1;slot<=16;slot++){const info=m.get(slot),b=document.createElement('button');b.className=`pad ${info?'filled':'empty'} ${slot===selectedSlot?'selected':''}`;b.dataset.slot=slot;b.innerHTML=`<div class="pad-number">M${String(slot).padStart(2,'0')} <span class="key">${padKeys[slot-1].toUpperCase()}</span></div><div class="pad-name">${esc(info?info.name:'Empty')}</div><div class="pad-meta">${info?`${info.event_count} notes · ${info.length_beats.toFixed(2)} beats`:'select → record'}</div>`;b.onclick=()=>selectAndTrigger(slot);$('pads').appendChild(b)}$('momentName').placeholder=`Moment ${String(selectedSlot).padStart(2,'0')}`}function renderChain(){const m=slotMap(),row=$('chain');row.innerHTML='';if(!state.chain.length){row.innerHTML='<span class="small">No sentence yet.</span>';return}state.chain.forEach((slot,i)=>{const c=document.createElement('span'),info=m.get(slot);c.className='chain-chip';c.textContent=`${i+1}. ${info?info.name:`M${slot}`}`;row.appendChild(c)})}function renderAll(){renderPads();renderChain()}async function refresh(){const r=await fetch('/api/state',{cache:'no-store'});state=await r.json();renderAll();status(`${state.slots.length}/16 moments stored.`,'Ready.')}
async function selectAndTrigger(slot){selectedSlot=slot;renderPads();if(slotMap().has(slot))await trigger(slot);else status(`M${String(slot).padStart(2,'0')} selected for recording.`)}async function trigger(slot){flash(slot);if(chainCapture){state.chain.push(slot);await api('/api/chain',{slots:state.chain});renderChain()}try{const d=await api('/api/render',{slot,...controls()});schedule(d.render);status(`${d.moment.name}: ${d.render.cycle_strengths.map(v=>Math.round(v*100)+'%').join(' → ')}`,'Played.')}catch(e){status(e.message,'Error:')}}function flash(slot){const p=document.querySelector(`.pad[data-slot="${slot}"]`);if(!p)return;p.classList.add('flash');setTimeout(()=>p.classList.remove('flash'),110)}
function ensureAudio(){if(!audioContext)audioContext=new(window.AudioContext||window.webkitAudioContext)();if(audioContext.state==='suspended')audioContext.resume();return audioContext}function schedule(render){const beat=msPerBeat();if(midiOutput){const base=performance.now()+35;render.events.forEach(e=>{midiOutput.send([0x90|(e.channel&15),e.note,e.velocity],base+e.start*beat);midiOutput.send([0x80|(e.channel&15),e.note,0],base+(e.start+e.duration)*beat)})}else{const ctx=ensureAudio(),base=ctx.currentTime+.035,sec=beat/1000;render.events.forEach(e=>audition(ctx,e,base,sec))}}function audition(ctx,e,base,sec){const start=base+e.start*sec,end=start+Math.max(.03,e.duration*sec),o=ctx.createOscillator(),g=ctx.createGain(),f=ctx.createBiquadFilter();o.type='triangle';o.frequency.value=440*Math.pow(2,(e.note-69)/12);f.type='lowpass';f.frequency.value=2600;const level=Math.min(.14,.025+e.velocity/127*.08);g.gain.setValueAtTime(.0001,start);g.gain.exponentialRampToValueAtTime(level,start+.012);g.gain.setValueAtTime(level,Math.max(start+.013,end-.045));g.gain.exponentialRampToValueAtTime(.0001,end);o.connect(f);f.connect(g);g.connect(ctx.destination);o.start(start);o.stop(end+.02)}
async function startRecording(){const existing=slotMap().get(selectedSlot);if(existing&&!confirm(`Replace ${existing.name} in M${String(selectedSlot).padStart(2,'0')}?`))return;if(!midiInput){status('Connect a MIDI input first, or use Load 4 demos to test playback.','Record blocked.');return}recording=true;recordedEvents=[];activeNotes.clear();recordStartMs=null;$('recordBtn').classList.add('recording');status(`Play the gesture for M${String(selectedSlot).padStart(2,'0')}. Recording begins on the first note.`,'Recording armed.')}function closeNote(key,now){const a=activeNotes.get(key);if(!a||recordStartMs===null)return;recordedEvents.push({note:a.note,velocity:a.velocity,channel:a.channel,start:(a.started-recordStartMs)/msPerBeat(),duration:Math.max(.03,(now-a.started)/msPerBeat())});activeNotes.delete(key)}async function stopRecording(){if(!recording)return;const now=performance.now();[...activeNotes.keys()].forEach(k=>closeNote(k,now));recording=false;$('recordBtn').classList.remove('recording');if(!recordedEvents.length){status('Nothing stored because no completed notes were captured.','Record stopped.');return}const length=Math.max(...recordedEvents.map(e=>e.start+e.duration));try{const d=await api('/api/store',{slot:selectedSlot,name:$('momentName').value.trim(),events:recordedEvents,length_beats:length});state=d.state;$('momentName').value='';renderAll();status(`${d.stored.name}: ${d.stored.event_count} notes, ${d.stored.length_beats.toFixed(2)} beats.`,'Stored.')}catch(e){status(e.message,'Error:')}}function handleMidi(ev){const[st,n,v=0]=ev.data,type=st&0xf0,ch=st&15,now=performance.now(),key=`${ch}:${n}`;if(recording){if(type===0x90&&v>0){if(recordStartMs===null)recordStartMs=now;activeNotes.set(key,{note:n,velocity:v,channel:ch,started:now})}else if(type===0x80||(type===0x90&&v===0))closeNote(key,now)}}
async function connectMidi(){if(!navigator.requestMIDIAccess){status('This browser does not expose Web MIDI. Playback still works with the audition synth; recording needs Web MIDI.','MIDI unavailable.');return}try{midiAccess=await navigator.requestMIDIAccess();populateMidi();status('Choose an input for recording and an output for real-synth playback.','MIDI connected.')}catch(e){status(e.message,'MIDI error:')}}function populateMidi(){const i=$('midiIn'),o=$('midiOut');i.innerHTML='<option value="">No MIDI input</option>';o.innerHTML='<option value="">Audition synth</option>';[...midiAccess.inputs.values()].forEach(x=>i.add(new Option(x.name||x.id,x.id)));[...midiAccess.outputs.values()].forEach(x=>o.add(new Option(x.name||x.id,x.id)));const first=[...midiAccess.inputs.values()][0];if(first){i.value=first.id;chooseInput(first.id)}}function chooseInput(id){if(midiInput)midiInput.onmidimessage=null;midiInput=id&&midiAccess?midiAccess.inputs.get(id):null;if(midiInput)midiInput.onmidimessage=handleMidi}function chooseOutput(id){midiOutput=id&&midiAccess?midiAccess.outputs.get(id):null}
async function toggleChain(){chainCapture=!chainCapture;$('chainCaptureBtn').classList.toggle('active',chainCapture);status(chainCapture?'Every triggered moment is appended to the sentence.':'Pad triggers no longer append to the sentence.',chainCapture?'Chain capture on.':'Chain capture off.')}async function playChain(){if(!state.chain.length){status('Capture some moments first.','Chain empty.');return}try{const d=await api('/api/render-chain',{...controls()});schedule(d.render);status(`${d.slots.length} moments · ${d.render.length_beats.toFixed(2)} beats.`,'Sentence played.')}catch(e){status(e.message,'Error:')}}async function clearChain(){if(!state.chain.length||!confirm(`Clear the ${state.chain.length}-moment sentence? Stored moments will not be changed.`))return;state.chain=[];await api('/api/chain',{slots:[]});renderChain();status('Stored moments were preserved.','Chain cleared.')}async function clearSelected(){const info=slotMap().get(selectedSlot);if(!info||!confirm(`Clear ${info.name} from M${String(selectedSlot).padStart(2,'0')}?`))return;state=await api('/api/clear',{slot:selectedSlot,confirm:true});renderAll();status(`${info.name} removed.`,'Slot cleared.')}
$('recordBtn').onclick=startRecording;$('stopBtn').onclick=stopRecording;$('demoBtn').onclick=async()=>{state=await api('/api/demo');renderAll();status('Pads 1–4 now contain deterministic example moments.','Demos loaded.')};$('chainCaptureBtn').onclick=toggleChain;$('playChainBtn').onclick=playChain;$('clearChainBtn').onclick=clearChain;$('clearSlotBtn').onclick=clearSelected;$('midiBtn').onclick=connectMidi;$('midiIn').onchange=e=>chooseInput(e.target.value);$('midiOut').onchange=e=>chooseOutput(e.target.value);['repeat','evolve'].forEach(id=>$(id).addEventListener('input',labels));$('surprise').addEventListener('input',()=>{if(Number($('surprise').value)>0&&Number($('repeat').value)<3)$('repeat').value=3;labels()});document.addEventListener('keydown',e=>{if(e.repeat||e.target.matches('input,select,button'))return;const i=padKeys.indexOf(e.key.toLowerCase());if(i>=0){e.preventDefault();selectAndTrigger(i+1)}});labels();refresh().catch(e=>status(e.message,'Startup error:'));
</script></body></html>'''
